<?php
require_once __DIR__.'/config/auth.php';$user=require_login();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT a.*,u.full_name creator,uu.full_name updater FROM archives a LEFT JOIN users u ON u.id=a.created_by LEFT JOIN users uu ON uu.id=a.updated_by WHERE a.id=?');$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Archive not found.');}log_activity('archive viewed','archive',$id,$a['ref_number'],'Archive opened',$user);$s=db()->prepare('SELECT * FROM archive_documents WHERE archive_id=? ORDER BY slot_no');$s->execute([$id]);$docs=$s->fetchAll();$s=db()->prepare('SELECT p.*,u.full_name received_name FROM payments p LEFT JOIN users u ON u.id=p.received_by WHERE p.archive_id=? LIMIT 1');$s->execute([$id]);$pay=$s->fetch();$title='View Archive';require __DIR__.'/includes/header.php';
?><div class="page-head"><div><span class="eyebrow">ARCHIVE</span><h1><?=e($a['ref_number'])?></h1><p class="muted">Entered <?=e(date('M j, Y g:i A',strtotime($a['created_at'])))?> by <?=e($a['creator']??'-')?></p><?php if($a['updated_by']):?><p class="muted">Last updated <?=e(date('M j, Y g:i A',strtotime($a['updated_at'])))?> by <?=e($a['updater']??'-')?></p><?php endif;?></div><div class="actions"><?php if($pay):?><a class="btn light" href="payment_receipt.php?id=<?=$pay['id']?>" target="_blank" rel="noopener">Print payment</a><?php endif;?><?php if($user['role']==='admin'):?><a class="btn light" href="archive_edit.php?id=<?=$id?>">Edit</a><form method="post" action="archive_delete.php" data-confirm="Delete this archive and its documents?"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn danger">Delete</button></form><?php endif;?></div></div><div class="card form-section"><h2>Documents</h2><div class="document-grid archive-documents"><?php foreach($docs as $d):$ext=strtolower(pathinfo($d['file_path'],PATHINFO_EXTENSION));?><div class="upload-tile"><strong>Document <?=$d['slot_no']?></strong><p class="muted"><?=e($d['original_name'])?></p><?php if(in_array($ext,['jpg','jpeg','png'],true)):?><button type="button" class="image-button" data-full-image="<?=e($d['file_path'])?>"><img class="archive-image small" src="<?=e($d['file_path'])?>" alt="<?=e($d['original_name'])?>"></button><?php endif;?><a class="btn light" target="_blank" rel="noopener" href="<?=e($d['file_path'])?>">Download</a></div><?php endforeach;?></div></div><div class="card"><h2>Payment</h2><?php if($pay):?><p><strong><?=e($pay['sender_name'])?></strong><br><?=e($pay['sender_phone'])?></p><p><strong><?=e(CURRENCY.number_format((float)$pay['amount'],2))?></strong></p><p class="muted"><?=e(date('M j, Y g:i A',strtotime($pay['paid_at'])))?> · Received by <?=e($pay['received_name']??'-')?></p><?php else:?><p class="muted">-</p><?php if($user['role']==='admin'):?><a class="btn light" href="archive_edit.php?id=<?=$id?>">Add payment</a><?php endif;?><?php endif;?></div><div class="image-viewer" id="image-viewer" hidden><button type="button" class="image-viewer-close" aria-label="Close">&times;</button><img id="image-viewer-image" alt="Document preview"></div><?php require __DIR__.'/includes/footer.php';

